@Test
public void testInvalidInputStream_1_oe() throws IOException, ExecutionException, InterruptedException {

  try (AsyncHttpClient c = asyncHttpClient()) {
    HttpHeaders h = new DefaultHttpHeaders().add(CONTENT_TYPE, HttpHeaderValues.APPLICATION_X_WWW_FORM_URLENCODED);

    InputStream is = new InputStream() {

      int readAllowed;

      @Override
      public int available() {
        return 1; // Fake
      }

      @Override
      public int read() {
        int fakeCount = readAllowed++;
        if (fakeCount == 0) {
          return (int) 'a';
        } else if (fakeCount == 1) {
          return (int) 'b';
        } else if (fakeCount == 2) {
          return (int) 'c';
        } else {
          return -1;
        }
      }
    };

    Response resp = c.preparePost(getTargetUrl()).setHeaders(h).setBody(is).execute().get();
    assertNotNull(resp);
}
}

