@Test(groups = "online")
public void testMaxTotalConnectionsExceedingException_1_oe() throws IOException {
  String[] urls = new String[]{"https://google.com", "https://github.com"};

  AsyncHttpClientConfig config = config()
          .setConnectTimeout(1000)
          .setRequestTimeout(5000)
          .setKeepAlive(false)
          .setMaxConnections(1)
          .setMaxConnectionsPerHost(1)
          .build();

  try (AsyncHttpClient client = asyncHttpClient(config)) {
    List<ListenableFuture<Response>> futures = new ArrayList<>();
    for (String url : urls) {
      futures.add(client.prepareGet(url).execute());
    }

    boolean caughtError = false;
    int i;
    for (i = 0; i < urls.length; i++) {
      try {
        futures.get(i).get();
      } catch (Exception e) {
        // assert that 2nd request fails, because
        // maxTotalConnections=1
        caughtError = true;
        break;
      }
    }

    Assert.assertEquals(1, i);
}
}

